<?php /** One condition row: field · op · value (· args). Data: i, c (field, op, value, args), voc, lists (statuses, queues, categories, types, organizations, tags) */ $f = (string) ($c['field'] ?? ''); $op = (string) ($c['op'] ?? 'eq'); $v = $c['value'] ?? ''; $v = is_array($v) ? implode(', ', array_map('strval', $v)) : (is_bool($v) ? ($v ? 'true' : 'false') : (string) $v); ?>
<div class="row g-1 mb-2 align-items-center rule-cond-row" id="rule-cond-<?= (int) $i ?>">
    <div class="col-12 col-md-4"><select name="conditions_rows[<?= (int) $i ?>][field]" class="form-select btn-touch" id="rule-cond-<?= (int) $i ?>-field" aria-label="Field"><option value="">— no condition —</option><?php foreach ($voc['fields'] as $k => $meta): ?><option value="<?= e($k) ?>" <?= $f === $k ? 'selected' : '' ?>><?= e($meta[0]) ?></option><?php endforeach; ?></select></div>
    <div class="col-5 col-md-2"><select name="conditions_rows[<?= (int) $i ?>][op]" class="form-select btn-touch" id="rule-cond-<?= (int) $i ?>-op" aria-label="Op"><?php foreach (RULE_OPS as $k => $l): ?><option value="<?= e($k) ?>" <?= $op === $k ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
    <div class="col-7 col-md-4"><input type="text" name="conditions_rows[<?= (int) $i ?>][value]" class="form-control btn-touch" id="rule-cond-<?= (int) $i ?>-value" value="<?= e($v) ?>" placeholder="value, or a,b,c — or setting:auto_close_days" list="rule-values-<?= e($f) ?>"></div>
    <div class="col-12 col-md-2"><select name="conditions_rows[<?= (int) $i ?>][args]" class="form-select btn-touch" id="rule-cond-<?= (int) $i ?>-args" aria-label="Since"><option value="">since…</option><?php foreach (RULE_DATE_ARGS as $k => $l): ?><option value="<?= e($k) ?>" <?= ($c['args'] ?? '') === $k ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
</div>
